package io.github.jesterportfolio.hearth.survival.enchants;
import java.util.*;import java.util.function.*;import java.util.random.RandomGenerator;
/** 장착한 ID만 조회한다. 이벤트마다 전체 카탈로그/파일/DB를 순회하지 않는다. */
public final class EnchantEngine {
    public record Invocation(EnchantDefinition definition,EnchantDefinition.Effect effect,int level,double duration,Map<String,Double> variables){}
    private record Key(UUID player,String id){}
    private long nextExpiry;private final Map<Key,Long> cooldowns=new HashMap<>();private final LongSupplier clock;private final RandomGenerator random;
    public EnchantEngine(LongSupplier clock,RandomGenerator random){this.clock=clock;this.random=random;}
    public List<Invocation> plan(UUID player,Map<String,Integer> equipped,Map<String,EnchantDefinition> catalog,EnchantDefinition.Trigger trigger,String world,Map<String,Double> input){var out=new ArrayList<Invocation>();long now=clock.getAsLong();if(now>=nextExpiry){cooldowns.entrySet().removeIf(e->e.getValue()<=now);nextExpiry=now+1000;}for(var enchant:equipped.entrySet()){var def=catalog.get(enchant.getKey());if(def==null||!def.enabled()||!def.worlds().isEmpty()&&!def.worlds().contains(world)||enchant.getValue()<1||enchant.getValue()>def.maxLevel())continue;var vars=new HashMap<>(input);vars.put("level",enchant.getValue().doubleValue());for(int i=0;i<def.rules().size();i++){var rule=def.rules().get(i);var key=new Key(player,def.id());if(rule.trigger()!=trigger||cooldowns.getOrDefault(key,0L)>now||rule.condition().evaluate(vars)==0)continue;double chance=Math.clamp(rule.chance().evaluate(vars),0,1);if(chance==0||random.nextDouble()>=chance)continue;double wait=Math.clamp(rule.cooldown().evaluate(vars),0,86400000);if(wait>0){if(cooldowns.size()>=16384)throw new IllegalStateException("ENCHANT_COOLDOWN_CAPACITY");cooldowns.put(key,now+(long)wait);}double duration=Math.clamp(rule.duration().evaluate(vars),1,120000);for(var effect:rule.effects())out.add(new Invocation(def,effect,enchant.getValue(),duration,Map.copyOf(vars)));}}return List.copyOf(out);}
    public Map<UUID,Map<String,Long>> cooldowns(){var out=new HashMap<UUID,Map<String,Long>>();cooldowns.forEach((key,until)->out.computeIfAbsent(key.player(),x->new HashMap<>()).put(key.id(),until));out.replaceAll((key,value)->Map.copyOf(value));return Map.copyOf(out);}
    public void restore(Map<UUID,Map<String,Long>> values){for(var player:values.entrySet())for(var entry:player.getValue().entrySet()){if(cooldowns.size()>=16384)throw new IllegalStateException("ENCHANT_COOLDOWN_CAPACITY");if(entry.getValue()>clock.getAsLong())cooldowns.merge(new Key(player.getKey(),entry.getKey()),entry.getValue(),Math::max);}}
    public void clear(){cooldowns.clear();}
}
